    .replace(/\\s*Direct-delivery guard refreshed provenance at [0-9a-f]{12};[\\s\\S]*$/u, "")
    .trim();
  let suffix = ` Direct-delivery guard refreshed provenance at ${head.slice(0, 12)}; the principal's statement is unchanged.`;
  if (addedPaths.length > 0) {
    suffix += ` The direct advance also carries ${addedPaths.map((path) => JSON.stringify(path)).join(", ")}.`;
  }
  if (laterEntryRefs.length > 0) {
    suffix += ` Later journal fact(s) ${laterEntryRefs.join(", ")} remain recorded before this refresh.`;
  }
  return `${base}${suffix}`;
