/**
 * The ordinary fast-forward of a prepared review leaves the merged commit as the tip of BOTH the
 * current branch and the prepared branch. A plain direct commit on the current branch is the tip of
 * only that branch. This is the bounded signal that lets the guard name a NEW review path without
 * treating every later commit as a delivery.
 */
function isPreparedBranchTip(repository: string, head: string): boolean {
  const current = git(repository, ["branch", "--show-current"]);
  const names = git(repository, ["for-each-ref", "--format=%(refname:short)", "--points-at", head, "refs/heads"]);
  if (names === null) return false;
